<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/admin_layout.php'))require_once __DIR__.'/../app/admin_layout.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/services_v1380.php';if(!sk1380_admin()){http_response_code(403);exit('Access denied.');}$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{sk1380_csrf_check();$pid=(int)$_POST['provider_id'];$act=(string)$_POST['action'];$p=sk1380_provider_by_id($pid,false);if(!$p)throw new RuntimeException('Provider not found.');if($act==='approve'){$pdo=sk1380_db();$pdo->beginTransaction();$pdo->prepare('UPDATE service_provider_profiles_v1380 SET status="approved",verification_status=IF(verification_status="unverified","reviewed",verification_status),approved_by=?,approved_at=NOW(),updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([sk1380_uid(),sk1380_tid(),$pid]);$q=$pdo->prepare('SELECT id FROM service_packages_v1380 WHERE tenant_id=? AND package_key="free" LIMIT 1');$q->execute([sk1380_tid()]);$free=(int)$q->fetchColumn();if($free){$q=$pdo->prepare('SELECT 1 FROM service_subscriptions_v1380 WHERE tenant_id=? AND provider_id=? AND status="active" AND (ends_at IS NULL OR ends_at>=NOW()) LIMIT 1');$q->execute([sk1380_tid(),$pid]);if(!$q->fetchColumn())$pdo->prepare('INSERT INTO service_subscriptions_v1380(tenant_id,provider_id,package_id,status,starts_at,ends_at,assigned_by,created_at,updated_at) VALUES(?,?,?,"active",NOW(),NULL,?,NOW(),NOW())')->execute([sk1380_tid(),$pid,$free,sk1380_uid()]);}$pdo->commit();sk1380_apply_provider_access((int)$p['user_id'],true);$msg='Provider approved and portal access enabled.';}elseif($act==='verify'){sk1380_db()->prepare('UPDATE service_provider_profiles_v1380 SET verification_status="verified",verified_at=NOW(),verification_note=?,updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([trim((string)($_POST['note']??''))?:null,sk1380_tid(),$pid]);$msg='Provider marked verified.';}elseif($act==='suspend'){sk1380_db()->prepare('UPDATE service_provider_profiles_v1380 SET status="suspended",fast_service_enabled=0,updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([sk1380_tid(),$pid]);sk1380_apply_provider_access((int)$p['user_id'],false);$msg='Provider suspended.';}elseif($act==='reject'){sk1380_db()->prepare('UPDATE service_provider_profiles_v1380 SET status="rejected",verification_note=?,updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([trim((string)($_POST['note']??''))?:null,sk1380_tid(),$pid]);$msg='Application rejected.';}sk1380_db()->prepare('INSERT INTO service_moderation_log_v1380(tenant_id,entity_type,entity_id,actor_user_id,action_key,note,created_at) VALUES(?,"provider",?,?,?,?,NOW())')->execute([sk1380_tid(),$pid,sk1380_uid(),$act,trim((string)($_POST['note']??''))?:null]);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}$rows=[];try{$q=sk1380_db()->prepare('SELECT p.*,(SELECT GROUP_CONCAT(c.name ORDER BY c.sort_order SEPARATOR ", ") FROM service_provider_categories_v1380 pc JOIN service_categories_v1380 c ON c.id=pc.category_id WHERE pc.tenant_id=p.tenant_id AND pc.provider_id=p.id) categories FROM service_provider_profiles_v1380 p WHERE p.tenant_id=? ORDER BY FIELD(p.status,"pending","approved","suspended","rejected"),p.id DESC LIMIT 300');$q->execute([sk1380_tid()]);$rows=$q->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){$err=trim($err.' '.$e->getMessage());}sk1380_admin_header('Service Providers');?><div class="svc-admin"><section class="admin-hero"><div><span>PROVIDER ACCESS CONTROL</span><h1>Service Providers</h1><p>Every provider account remains locked until admin approval. Verification and suspension are separate controls.</p></div><a href="/admin/services.php">← Dashboard</a></section><?php if($msg):?><div class="notice ok"><?=sk1380_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=sk1380_h($err)?></div><?php endif;?><div class="admin-provider-list"><?php foreach($rows as $p):?><article><div><span class="state <?=sk1380_h($p['status'])?>"><?=sk1380_h(strtoupper($p['status']))?></span><?php if($p['verified_at']):?><span class="verified">✓ VERIFIED</span><?php endif;?><h2><?=sk1380_h($p['business_name']?:$p['display_name'])?></h2><p>User #<?=$p['user_id']?> · <?=sk1380_h($p['area'])?> · <?=sk1380_h($p['categories'])?></p><small><?=sk1380_h($p['bio'])?></small></div><form method="post"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="provider_id" value="<?=$p['id']?>"><input name="note" placeholder="Admin / verification note"><div class="actions"><?php if($p['status']!=='approved'):?><button name="action" value="approve">Approve</button><?php endif;?><button name="action" value="verify">Verify</button><button name="action" value="suspend" class="warn">Suspend</button><button name="action" value="reject" class="danger">Reject</button></div></form></article><?php endforeach;?></div></div><?php sk1380_admin_footer();